using System;using System.Collections.Generic;using UnityEngine;
public sealed class GreatswordMotor:INewWeaponMotor {
 readonly NewWeaponCombat owner;GearItem source;float release,end,used,power,tempo;bool skill,wave,done;public bool Busy{get;private set;}public string Phase{get;private set;}="Idle";public string BasicDescription=>"蓄势重斩；真实前方65度半角扇形，固定收招";public float Interval=>1.05f*owner.BasicTempo;
 public GreatswordMotor(NewWeaponCombat owner){this.owner=owner;}
 public bool Begin(bool skill,int selected){this.skill=skill;tempo=skill?1:owner.BasicTempo;wave=skill&&selected==1;source=owner.Combat.Gear.Main.Clone();power=owner.Hero.AttackPower;release=Time.time+(skill?(wave?.60f:.65f):.45f)*tempo;end=release+.5f;used=0;done=false;Busy=true;Phase="Startup";owner.Cooldown(skill,skill?owner.SkillDuration:Interval);owner.Animate("2H_Melee_Attack_Slice",skill?1.3f:.95f*tempo,2);owner.Emit("start",0,"twohand",Vector3.zero,Vector3.zero,0,null,0,0,false);return true;}
 public void Tick(){if(!Busy)return;if(Time.time<release){owner.Face(2.8f,20,90,ref used);return;}if(!done){done=true;Phase="Release";CombatFeedback.Find(owner)?.PlaySound(CombatSound.HeavySlash,owner.transform.position,.8f);if(wave)NewGroundShock.Spawn(owner,source,power*1.30f);else owner.NewSector(source,power*(skill?1.7f:1.05f),skill?3.1f:2.6f+owner.BasicReachBonus,skill?50:65,skill,skill?10:0);owner.Emit("release",0,"twohand",Vector3.zero,Vector3.zero,0,null,0,0,false);end=Time.time+.5f*tempo;}Phase="Recovery";if(Time.time>=end){Busy=false;Phase="Idle";owner.Emit("complete",0,"",Vector3.zero,Vector3.zero,0,null,0,0,false);}}
 public void Cancel(){if(Busy)owner.Emit("cancel",0,"",Vector3.zero,Vector3.zero,0,null,0,0,false);Busy=false;Phase="Cancelled";}
}
public sealed partial class NewWeaponCombat {
 internal void NewSector(GearItem source,float power,float reach,float angle,bool breakGuard,int phase){float area=phase>=10&&WeaponTraits.Has(source,2)?1.25f:1;reach*=area;var seen=new HashSet<Component>();Vector3 center=MeleeGeometry.Center(transform.position);Emit("volume",phase,"sector",center,transform.forward,reach,null,0,0,false);foreach(var c in Physics.OverlapSphere(center,reach,~0,QueryTriggerInteraction.Ignore)){if(!CombatAim.Legal(c,hero))continue;var enemy=c.GetComponentInParent<CombatEnemy>();var node=c.GetComponentInParent<AdventureResource>();Component target=enemy!=null?(Component)enemy:node;if(target==null||seen.Contains(target))continue;Vector3 point=CombatAim.OverlapPoint(c,center),offset=Vector3.ProjectOnPlane(point-center,Vector3.up);if(offset.sqrMagnitude>.001f&&Vector3.Angle(transform.forward,offset)>angle)continue;if(!AdventureCombat.Sight(center,point,target)){Emit("obstructed",phase,"sector",center,point,reach,target,0,0,false);continue;}seen.Add(target);float before=enemy!=null?enemy.Health.Current:node.Health;if(enemy!=null){WeaponHit.Apply(hero,enemy,power,point,transform.forward,source,phase>=10);if(breakGuard&&!enemy.Health.Dead){var control=enemy.GetComponent<EnemyWeaponControl>()??enemy.gameObject.AddComponent<EnemyWeaponControl>();bool applied=control.Break(.75f);Emit(applied?"guard-broken":"control-immune",phase,"",center,point,0,enemy,0,0,false);}}else node.Hit(power,hero);float after=enemy!=null?enemy.Health.Current:node.Health;Emit("contact",phase,"sector",center,point,reach,target,before,after,false);}NewWeaponArc.Show(center,transform.forward,reach,angle,gameObject.scene,hero);}
}
public sealed class NewWeaponArc:MonoBehaviour {
 Material material;ThirdPersonHero hero;float age;
 public static void Show(Vector3 center,Vector3 forward,float r,float angle,UnityEngine.SceneManagement.Scene scene,ThirdPersonHero h){var g=new GameObject("真实扇形边界");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,scene);var v=g.AddComponent<NewWeaponArc>();v.hero=h;v.material=new Material(Shader.Find("Universal Render Pipeline/Unlit")){color=new Color(1,.65f,.25f)};var l=g.AddComponent<LineRenderer>();l.sharedMaterial=v.material;l.startWidth=l.endWidth=.04f;l.positionCount=35;l.SetPosition(0,center);for(int i=0;i<=32;i++)l.SetPosition(i+1,center+Quaternion.AngleAxis(-angle+2*angle*i/32,Vector3.up)*forward*r);l.SetPosition(34,center);}
 void Update(){if(hero==null||hero.Health.Dead){Destroy(gameObject);return;}if(hero.GameplayPaused||Time.timeScale<=0)return;age+=Time.deltaTime;if(age>.25f)Destroy(gameObject);}void OnDestroy(){if(material!=null)Destroy(material);}
}
public sealed class NewGroundShock:MonoBehaviour {
 ThirdPersonHero hero;NewWeaponCombat observer;GearItem source;Vector3 direction;float damage,travel,radius=.3f,limit=8;readonly HashSet<Component> seen=new HashSet<Component>();Material material;
 public static void Spawn(NewWeaponCombat o,GearItem item,float damage){var g=new GameObject("裂地冲击真实碰撞波");UnityEngine.SceneManagement.SceneManager.MoveGameObjectToScene(g,o.gameObject.scene);var p=g.AddComponent<NewGroundShock>();p.hero=o.Hero;p.observer=o;p.source=item.Clone();p.damage=damage;float area=WeaponTraits.Has(item,2)?1.25f:1;p.radius=.3f*area;p.limit=8*area;p.direction=o.transform.forward;g.transform.position=o.transform.position+Vector3.up*.65f+o.transform.forward*.5f;p.material=new Material(Shader.Find("Universal Render Pipeline/Unlit")){color=new Color(1,.7f,.2f)};var l=g.AddComponent<LineRenderer>();l.sharedMaterial=p.material;l.startWidth=l.endWidth=p.radius*2;l.positionCount=2;o.Emit("wave-spawn",0,"",g.transform.position,p.direction,p.radius,null,0,0,false);}
 void Update(){if(hero==null||hero.Health.Dead){Destroy(gameObject);return;}if(hero.GameplayPaused||Time.timeScale<=0)return;float step=Mathf.Min(8*Time.deltaTime,limit-travel);var hits=Physics.SphereCastAll(transform.position,radius,direction,step,~0,QueryTriggerInteraction.Ignore);Array.Sort(hits,(a,b)=>a.distance.CompareTo(b.distance));var initial=Physics.OverlapSphere(transform.position,radius,~0,QueryTriggerInteraction.Ignore);Array.Sort(initial,(a,b)=>((a.GetComponentInParent<CombatEnemy>()==null&&a.GetComponentInParent<AdventureResource>()==null)?0:1).CompareTo((b.GetComponentInParent<CombatEnemy>()==null&&b.GetComponentInParent<AdventureResource>()==null)?0:1));foreach(var c in initial)if(CombatAim.Legal(c,hero)&&!Contact(c,CombatAim.OverlapPoint(c,transform.position)))return;foreach(var hit in hits)if(CombatAim.Legal(hit.collider,hero)&&!Contact(hit.collider,hit.point))return;transform.position+=direction*step;travel+=step;var l=GetComponent<LineRenderer>();l.SetPosition(0,transform.position);l.SetPosition(1,transform.position-direction*.5f);observer?.Emit("wave-flight",0,"",transform.position,direction,radius,null,0,0,false);if(travel>=limit)Destroy(gameObject);}
 bool Contact(Collider c,Vector3 point){var e=c.GetComponentInParent<CombatEnemy>();var n=c.GetComponentInParent<AdventureResource>();Component t=e!=null?(Component)e:n;if(t==null){observer?.Emit("wave-blocked",0,"",transform.position,point,radius,c,0,0,false);Destroy(gameObject);return false;}if(seen.Contains(t))return true;seen.Add(t);float before=e!=null?e.Health.Current:n.Health;if(e!=null)WeaponHit.Apply(hero,e,damage,point,direction,source,true);else n.Hit(damage,hero);observer?.Emit("wave-contact",0,"",transform.position,point,radius,t,before,e!=null?e.Health.Current:n.Health,false);return true;}
 public static void Clear(ThirdPersonHero h){foreach(var p in FindObjectsByType<NewGroundShock>())if(p.hero==h){p.enabled=false;Destroy(p.gameObject);}}
 void OnDestroy(){if(material!=null)Destroy(material);}
}
